/**
 * Branded email header, base64-encoded for inline (CID) embedding.
 *
 * WHY EMBEDDED, NOT LINKED: email clients (Gmail especially) can't fetch
 * `http://localhost` images, and even in production a remote <img> is often
 * proxied/blocked. Attaching the image as a CID MIME part makes it render in
 * every environment without any hosting. It's a separate MIME part, so it does
 * NOT count toward Gmail's ~102KB HTML clip limit.
 *
 * The PNG is a 2x composite of public/email/quiktrack-header.png with the
 * QUIKIT logo baked in (see scratchpad/composite-header.html). Regenerate by
 * re-running the composite + scripts/encode-header if the banner changes.
 */
export const EMAIL_HEADER_CID = "quiktrack-header";

const EMAIL_HEADER_PNG_BASE64 =
  "";

/**
 * nodemailer attachment for the branded header, referenced in HTML as
 * `<img src="cid:${EMAIL_HEADER_CID}">`. Marked inline (content-disposition)
 * so it renders in the body rather than showing as a file attachment.
 */
export function brandedEmailAttachments() {
  return [
    {
      filename: "quiktrack-header.png",
      content: Buffer.from(EMAIL_HEADER_PNG_BASE64, "base64"),
      contentType: "image/png",
      cid: EMAIL_HEADER_CID,
      contentDisposition: "inline" as const,
    },
  ];
}
